/* KPOS Foundation Completion Pack - net reports, customer loyalty detail, return printing, safer actions, desktop tables */
(function(){
  const desktopMQ=window.matchMedia('(min-width:980px)');
  const isDesktop=()=>desktopMQ.matches;
  const baseModalView=window.modalView;
  const baseRender=window.render;
  const baseCancelInvoice=window.cancelInvoice;
  const baseProductCards=window.productCards;
  const baseCustomerCards=window.customerCards;
  const baseInvoiceCards=window.invoiceCards;

  function ensure(){
    if(!Array.isArray(db.returns))db.returns=[];
    if(!Array.isArray(db.vouchers))db.vouchers=[];
    (db.customers||[]).forEach(c=>{c.points=Math.max(0,Number(c.points)||0)});
    (db.invoices||[]).forEach(i=>{i.returnedAmount=Math.max(0,Number(i.returnedAmount)||0)});
  }
  ensure();

  function activeReturnsForInvoice(invId){return (db.returns||[]).filter(r=>r.invoiceId===invId&&r.status!=='Đã hủy')}
  function returnQty(invId,sourceIndex){return activeReturnsForInvoice(invId).reduce((sum,r)=>sum+(r.items||[]).filter(x=>x.sourceIndex===sourceIndex).reduce((a,b)=>a+(Number(b.qty)||0),0),0)}
  function invoiceFullyReturned(inv){return (inv.items||[]).length>0&&(inv.items||[]).every((it,idx)=>returnQty(inv.id,idx)>=(Number(it.qty)||0))}
  function netInvoiceValue(inv){return Math.max(0,(Number(inv.total)||0)-(Number(inv.returnedAmount)||0))}

  function reportBounds(){
    const now=new Date(),preset=state.foundationReportPreset||'30';
    if(preset==='all')return {start:null,end:null};
    if(preset==='custom'){
      const start=state.foundationReportFrom?new Date(state.foundationReportFrom+'T00:00:00'):null;
      const end=state.foundationReportTo?new Date(state.foundationReportTo+'T23:59:59.999'):null;
      return {start,end};
    }
    const days=Math.max(1,Number(preset)||30),end=new Date(now),start=new Date(now);start.setHours(0,0,0,0);start.setDate(start.getDate()-(days-1));return {start,end};
  }
  function inRange(date){const {start,end}=reportBounds(),d=new Date(date);return (!start||d>=start)&&(!end||d<=end)}
  window.setFoundationReportPreset=v=>{state.foundationReportPreset=v;render()};
  window.applyFoundationReportRange=()=>{state.foundationReportFrom=$('#foundationFrom')?.value||'';state.foundationReportTo=$('#foundationTo')?.value||'';state.foundationReportPreset='custom';render()};

  window.reportsView=reportsView=function(){
    ensure();
    const invs=(db.invoices||[]).filter(i=>i.status!=='Đã hủy'&&inRange(i.date));
    const returns=(db.returns||[]).filter(r=>r.status!=='Đã hủy'&&inRange(r.date));
    const pays=(db.payments||[]).filter(p=>p.status!=='Đã hủy'&&inRange(p.date));
    const grossRevenue=invs.reduce((a,b)=>a+(Number(b.total)||0),0);
    const returnValue=returns.reduce((a,b)=>a+(Number(b.amount)||0),0);
    const netRevenue=grossRevenue-returnValue;
    const grossProfit=invs.reduce((a,b)=>a+(Number(b.profit)||0),0);
    const returnProfitImpact=returns.reduce((a,b)=>a+(Number(b.profitImpact)||0),0);
    const netProfit=grossProfit-returnProfitImpact;
    const currentDebt=(db.customers||[]).reduce((a,b)=>a+(Number(b.debt)||0),0);
    const methodTotal=method=>pays.filter(p=>p.method===method).reduce((a,b)=>a+(Number(b.amount)||0),0);
    const cash=methodTotal('Tiền mặt'),bank=methodTotal('Chuyển khoản'),card=methodTotal('Thẻ/POS');
    const grossItems=new Map(),returnedItems=new Map();
    invs.forEach(inv=>(inv.items||[]).forEach(it=>{const p=product(it.productId),x=grossItems.get(it.productId)||{name:p?.name||'Sản phẩm',qty:0,value:0};x.qty+=Number(it.qty)||0;x.value+=(Number(it.qty)||0)*(Number(it.price)||0);grossItems.set(it.productId,x)}));
    returns.forEach(r=>(r.items||[]).forEach(it=>{const x=returnedItems.get(it.productId)||{qty:0,value:0};x.qty+=Number(it.qty)||0;x.value+=(Number(it.qty)||0)*(Number(it.price)||0);returnedItems.set(it.productId,x)}));
    const rows=[...grossItems.entries()].map(([id,x])=>{const rr=returnedItems.get(id)||{qty:0,value:0};return {...x,id,returnQty:rr.qty,netQty:x.qty-rr.qty,netValue:x.value-rr.value}}).sort((a,b)=>b.netValue-a.netValue).slice(0,20);
    const preset=state.foundationReportPreset||'30';
    const buttons=[['1','Hôm nay'],['7','7 ngày'],['30','30 ngày'],['all','Tất cả']];
    return `${topbar('Báo cáo bán hàng','Doanh thu ròng • hoàn tiền • lợi nhuận • thanh toán • công nợ')}<div class="content foundation-report-page">
      <div class="foundation-report-toolbar"><div class="seg">${buttons.map(([v,l])=>`<button class="${preset===v?'active':''}" onclick="setFoundationReportPreset('${v}')">${l}</button>`).join('')}</div><div class="foundation-date-range"><input id="foundationFrom" type="date" value="${esc(state.foundationReportFrom||'')}"><span>đến</span><input id="foundationTo" type="date" value="${esc(state.foundationReportTo||'')}"><button class="btn ghost small" onclick="applyFoundationReportRange()">Áp dụng</button></div></div>
      <div class="foundation-kpis">
        ${stat('Doanh thu gộp',money(grossRevenue))}${stat('Trả hàng / hoàn tiền',money(returnValue))}${stat('Doanh thu ròng',money(netRevenue))}${stat('Lợi nhuận ròng',money(netProfit))}${stat('Tổng đơn',invs.length)}${stat('Phiếu trả / đổi',returns.length)}${stat('Tiền mặt ròng',money(cash))}${stat('Chuyển khoản ròng',money(bank))}${stat('Thẻ/POS ròng',money(card))}${stat('Công nợ hiện tại',money(currentDebt))}
      </div>
      <div class="foundation-report-columns">
        <section class="card foundation-table-card"><div class="foundation-panel-title"><b>Sản phẩm bán ròng</b><span>Đã trừ sản phẩm trả lại trong kỳ</span></div><div class="foundation-table foundation-products"><div class="foundation-tr head"><div>Sản phẩm</div><div class="right">Bán</div><div class="right">Trả</div><div class="right">Ròng</div><div class="right">Giá trị ròng</div></div>${rows.map(x=>`<div class="foundation-tr"><div><b>${esc(x.name)}</b></div><div class="right">${x.qty}</div><div class="right danger-text">${x.returnQty||0}</div><div class="right"><b>${x.netQty}</b></div><div class="right"><b>${money(x.netValue)}</b></div></div>`).join('')||'<div class="empty">Chưa có dữ liệu trong kỳ.</div>'}</div></section>
        <section class="card foundation-table-card"><div class="foundation-panel-title"><b>Hoàn tiền / trả hàng gần nhất</b><span>Dòng tiền âm đã được trừ khỏi phương thức thanh toán</span></div><div class="foundation-return-mini">${returns.slice(0,10).map(r=>{const c=customer(r.customerId);return `<button onclick="openInvoiceDetail(${r.invoiceId})"><span><b>${esc(r.code)}</b><small>${fmtDateTime(r.date)} • ${esc(c?.name||'Khách lẻ')}</small></span><span class="right"><b class="danger-text">-${money(r.refundPaid||0)}</b><small>${r.debtOffset?`Trừ nợ ${money(r.debtOffset)}`:esc(r.refundMethod||'')}</small></span></button>`}).join('')||'<div class="empty">Không có trả hàng trong kỳ.</div>'}</div></section>
      </div>
    </div>${nav()}`;
  };

  function customerDetailModal(m){
    ensure();const c=customer(m.c?.id)||m.c;if(!c)return baseModalView();const tab=m.tab||'orders';
    const invs=(db.invoices||[]).filter(i=>i.customerId===c.id),ims=(db.imeis||[]).filter(i=>i.customerId===c.id),ws=(db.warranties||[]).filter(w=>w.phone===c.phone||ims.some(i=>i.value===w.imei)),ps=(db.payments||[]).filter(p=>p.customerId===c.id),rs=(db.returns||[]).filter(r=>r.customerId===c.id&&r.status!=='Đã hủy');
    let body='';
    if(tab==='orders')body=invs.map(i=>`<button class="foundation-customer-line" onclick="openInvoiceDetail(${i.id})"><span><b>${esc(i.code)}</b><small>${fmtDateTime(i.date)} • ${esc(i.status||'')}</small></span><span class="right"><b>${money(netInvoiceValue(i))}</b>${i.returnedAmount?`<small class="danger-text">Đã trả ${money(i.returnedAmount)}</small>`:''}</span></button>`).join('')||'<div class="empty">Chưa có đơn hàng</div>';
    if(tab==='imei')body=imeiCards(ims);
    if(tab==='warranty')body=warrantyCards(ws);
    if(tab==='payments')body=ps.map(p=>`<div class="foundation-customer-line"><span><b>${esc(p.code)}</b><small>${fmtDateTime(p.date)} • ${esc(p.method||'')} • ${esc(p.status||'')}</small></span><b class="${Number(p.amount)<0?'danger-text':''}">${money(p.amount)}</b></div>`).join('')||'<div class="empty">Chưa có thanh toán</div>';
    if(tab==='returns')body=rs.map(r=>`<button class="foundation-customer-line" onclick="openInvoiceDetail(${r.invoiceId})"><span><b>${esc(r.code)}</b><small>${fmtDateTime(r.date)} • ${r.type==='exchange'?'Đổi hàng':'Trả hàng'}</small></span><span class="right"><b>${money(r.amount)}</b><small>${r.debtOffset?`Trừ nợ ${money(r.debtOffset)}`:esc(r.refundMethod||'')}</small></span></button>`).join('')||'<div class="empty">Chưa có trả / đổi hàng</div>';
    if(tab==='loyalty'){
      const used=invs.filter(i=>i.voucherCode||Number(i.pointsUsed)>0||Number(i.pointsEarned)>0);
      const pointValue=Number(db.loyaltySettings&&db.loyaltySettings.pointValue)||0;
      const pointMoney=(Number(c.points)||0)*pointValue;
      const loyaltyRows=used.map(i=>{const vc=i.voucherCode?'Voucher '+esc(i.voucherCode):'Không voucher';const usedText=i.pointsUsed?' • dùng '+i.pointsUsed+' điểm':'';const earned=i.pointsEarned?'+'+i.pointsEarned+' điểm':'';const discount=i.pointsDiscount?'Giảm '+money(i.pointsDiscount):'';return `<button class="foundation-customer-line" onclick="openInvoiceDetail(${i.id})"><span><b>${esc(i.code)}</b><small>${vc}${usedText}</small></span><span class="right"><b>${earned}</b><small>${discount}</small></span></button>`}).join('');
      body=`<div class="foundation-loyalty-summary"><div><span>Điểm hiện có</span><b>${Number(c.points)||0}</b></div><div><span>Giá trị quy đổi</span><b>${money(pointMoney)}</b></div></div>${loyaltyRows||'<div class="empty">Chưa có giao dịch điểm / voucher</div>'}`;
    }
    const returned=rs.reduce((a,b)=>a+(Number(b.amount)||0),0);
    return sheet(c.name,`<div class="foundation-profile-kpis"><div><span>Tổng mua ròng</span><b>${money(c.total||0)}</b></div><div><span>Công nợ</span><b class="${c.debt?'danger-text':''}">${money(c.debt||0)}</b></div><div><span>Điểm</span><b>${Number(c.points)||0}</b></div><div><span>Đã trả / đổi</span><b>${money(returned)}</b></div></div><div class="card foundation-profile-info"><div><span>SĐT</span><b>${esc(c.phone||'—')}</b></div><div><span>CRM</span><b>${esc(c.status||'—')}</b></div>${c.address?`<div><span>Địa chỉ</span><b>${esc(c.address)}</b></div>`:''}</div>${c.debt?`<button class="btn success block" style="margin-top:10px" onclick="openDebtPayment(${c.id})">💰 THU CÔNG NỢ</button>`:''}<div class="tabs foundation-customer-tabs">${[['orders','Đơn hàng'],['imei','IMEI'],['warranty','Bảo hành'],['payments','Thanh toán'],['returns','Trả/đổi'],['loyalty','Điểm & voucher']].map(([v,l])=>`<button class="${tab===v?'active':''}" onclick="customerTab('${v}')">${l}</button>`).join('')}</div><div class="foundation-tab-body">${body}</div><div class="split-buttons" style="margin-top:12px"><button class="btn ghost" onclick="closeModal();openCustomerForm(${c.id})">Sửa thông tin</button><button class="btn danger" onclick="deleteCustomerSafe(${c.id})">Xóa khách</button></div>`);
  }

  window.deleteCustomerSafe=id=>{const c=customer(id);if(!c)return;const used=(db.invoices||[]).some(x=>x.customerId===id)||(db.payments||[]).some(x=>x.customerId===id)||(db.imeis||[]).some(x=>x.customerId===id)||(db.returns||[]).some(x=>x.customerId===id)||(Number(c.debt)||0)>0;if(used)return toast('Khách đã có giao dịch hoặc công nợ nên không thể xóa. Có thể sửa thông tin hoặc chuyển trạng thái CRM.');if(!confirm(`Xóa khách hàng "${c.name}"?`))return;db.customers=db.customers.filter(x=>x.id!==id);saveDB();state.modal=null;render();toast('Đã xóa khách hàng')};

  function invoiceDetailModal(inv){
    ensure();const c=customer(inv.customerId),rs=activeReturnsForInvoice(inv.id),done=invoiceFullyReturned(inv),net=netInvoiceValue(inv);
    return sheet(inv.code,`<div class="foundation-invoice-kpis"><div><span>Tổng hóa đơn</span><b>${money(inv.total||0)}</b></div><div><span>Đã trả / đổi</span><b class="${inv.returnedAmount?'danger-text':''}">${money(inv.returnedAmount||0)}</b></div><div><span>Giá trị còn lại</span><b>${money(net)}</b></div><div><span>Công nợ</span><b class="${inv.debt?'danger-text':''}">${money(inv.debt||0)}</b></div></div><div class="foundation-money-breakdown"><div><span>Khách hàng</span><b>${esc(c?.name||'Khách lẻ')}</b></div><div><span>Tạm tính</span><b>${money(inv.subtotal||inv.total||0)}</b></div>${inv.discount?`<div><span>Giảm giá</span><b>-${money(inv.discount)}</b></div>`:''}${inv.voucherDiscount?`<div><span>Voucher ${esc(inv.voucherCode||'')}</span><b>-${money(inv.voucherDiscount)}</b></div>`:''}${inv.pointsDiscount?`<div><span>Điểm (${Number(inv.pointsUsed)||0} điểm)</span><b>-${money(inv.pointsDiscount)}</b></div>`:''}${inv.surcharge?`<div><span>Phụ thu</span><b>+${money(inv.surcharge)}</b></div>`:''}${inv.shipping?`<div><span>Giao hàng</span><b>+${money(inv.shipping)}</b></div>`:''}<div><span>Thanh toán</span><b>${esc(inv.paymentMethod||'—')}</b></div>${inv.pointsEarned?`<div><span>Điểm được cộng</span><b class="success-text">+${inv.pointsEarned} điểm</b></div>`:''}</div><div class="section-title">Sản phẩm</div><div class="list foundation-invoice-items">${(inv.items||[]).map((it,idx)=>{const p=product(it.productId),rq=returnQty(inv.id,idx);return `<div class="item"><div class="item-main"><b>${esc(p?.name||'')}</b><div class="small muted">${it.qty} × ${money(it.price)}${rq?` • <span class="danger-text">đã trả ${rq}</span>`:''}</div>${it.imeis?.length?`<div class="taglist" style="margin-top:6px">${it.imeis.map(id=>`<span class="imei-tag mono">${esc(imeiObj(id)?.value||'')}</span>`).join('')}</div>`:''}</div><b>${money((Number(it.qty)||0)*(Number(it.price)||0))}</b></div>`}).join('')}</div>${rs.length?`<div class="section-title">Lịch sử trả / đổi</div><div class="foundation-return-history">${rs.map(r=>`<div><span><b>${esc(r.code)}</b><small>${fmtDateTime(r.date)} • ${r.type==='exchange'?'Đổi hàng':'Trả hàng'} • ${money(r.amount)}</small></span><span class="foundation-return-print"><button class="btn ghost small" onclick="openReturnPrint(${r.id},'K80')">K80</button><button class="btn ghost small" onclick="openReturnPrint(${r.id},'A4')">A4</button><button class="btn danger small" onclick="cancelReturn(${r.id})">Hủy phiếu</button></span></div>`).join('')}</div>`:''}<div class="small muted" style="margin-top:12px">${fmtDateTime(inv.date)} • ${esc(inv.status||'')}</div><div class="foundation-invoice-actions"><button class="btn ghost" onclick="previewTemplate('sale_k80','invoice',${inv.id})">Hóa đơn K80</button><button class="btn ghost" onclick="previewTemplate('sale_a4','invoice',${inv.id})">Hóa đơn A4</button><button class="btn danger" onclick="openReturnForm(${inv.id})" ${done||inv.status==='Đã hủy'?'disabled':''}>↩ Trả / đổi hàng</button><button class="btn danger" onclick="cancelInvoice(${inv.id})" ${inv.status==='Đã hủy'||rs.length?'disabled':''}>Hủy hóa đơn</button></div>${rs.length?'<div class="notice" style="margin-top:10px">Hóa đơn đã phát sinh trả/đổi nên không thể hủy trực tiếp. Hãy xử lý các phiếu trả/đổi trước.</div>':''}`);
  }

  window.cancelInvoice=id=>{const rs=activeReturnsForInvoice(id);if(rs.length)return toast('Hóa đơn đã có phiếu trả/đổi. Hãy hủy phiếu trả/đổi trước khi hủy hóa đơn.');return baseCancelInvoice?baseCancelInvoice(id):undefined};

  window.cancelReturn=id=>{
    ensure();const r=(db.returns||[]).find(x=>x.id===id);if(!r||r.status==='Đã hủy')return;const inv=invoice(r.invoiceId);if(!inv)return toast('Không tìm thấy hóa đơn gốc');
    for(const it of r.items||[]){const p=product(it.productId);if(!p)continue;if((Number(p.stock)||0)<(Number(it.qty)||0))return toast(`Không thể hủy: tồn kho ${p.name} không đủ để đảo phiếu.`);for(const iid of it.imeis||[]){const im=imeiObj(iid);if(!im||im.status!=='Trong kho'||im.invoiceId)return toast(`Không thể hủy: IMEI ${im?.value||iid} không còn ở trạng thái Trong kho.`)}}
    const reason=prompt('Lý do hủy phiếu trả/đổi:','Tạo nhầm phiếu')||'Hủy phiếu trả/đổi';if(!confirm(`Xác nhận hủy ${r.code}? Hệ thống sẽ đảo tồn kho, IMEI, công nợ và điểm.`))return;
    const c=customer(r.customerId);(r.items||[]).forEach(it=>{const p=product(it.productId);if(!p)return;p.stock=Math.max(0,(Number(p.stock)||0)-(Number(it.qty)||0));addMovement(p.id,-(Number(it.qty)||0),'RETURN_CANCEL',r.code,`Hủy phiếu trả hàng: ${reason}`);(it.imeis||[]).forEach(iid=>{const im=imeiObj(iid);if(im){im.status='Đã bán';im.customerId=inv.customerId||null;im.invoiceId=inv.id;im.soldDate=inv.date;im.warrantyStart=inv.date;im.warrantyEnd=addMonths(inv.date,p.warranty||0)}})});
    inv.debt=(Number(inv.debt)||0)+(Number(r.debtOffset)||0);if(c){c.debt=(Number(c.debt)||0)+(Number(r.debtOffset)||0);c.total=(Number(c.total)||0)+(Number(r.amount)||0);c.points=Math.max(0,(Number(c.points)||0)-(Number(r.pointsRestored)||0)+(Number(r.pointsReversed)||0))}
    (db.payments||[]).filter(p=>p.invoiceId===inv.id&&p.status==='Hoàn tiền'&&String(p.note||'').includes(r.code)).forEach(p=>p.status='Đã hủy');
    inv.returnedAmount=Math.max(0,(Number(inv.returnedAmount)||0)-(Number(r.amount)||0));r.status='Đã hủy';r.cancelledAt=new Date().toISOString();r.cancelReason=reason;
    const others=activeReturnsForInvoice(inv.id);inv.status=others.length?(invoiceFullyReturned(inv)?'Đã trả hàng':'Trả một phần'):(inv.debt>0?'Công nợ':'Hoàn thành');addActivity(`Đã hủy ${r.code} • ${reason}`);saveDB();state.modal={type:'invoiceDetail',inv};render();toast('Đã hủy phiếu trả/đổi và đảo dữ liệu liên quan');
  };

  function returnDocHtml(r,paper){const inv=invoice(r.invoiceId),c=customer(r.customerId),store=db.storeProfile||{},title=r.type==='exchange'?'PHIẾU ĐỔI HÀNG':'PHIẾU TRẢ HÀNG / HOÀN TIỀN';const items=(r.items||[]).map(it=>{const p=product(it.productId);return `<tr><td><b>${esc(p?.name||'Sản phẩm')}</b>${it.imeis?.length?`<div class="ret-print-imei">${it.imeis.map(id=>esc(imeiObj(id)?.value||String(id))).join('<br>')}</div>`:''}</td><td class="center">${it.qty}</td><td class="right">${money(it.price)}</td><td class="right">${money((Number(it.qty)||0)*(Number(it.price)||0))}</td></tr>`}).join('');return `<div class="return-print ${paper==='A4'?'a4':'k80'}"><header><h2>${esc(store.name||'KPOS')}</h2>${store.address?`<div>${esc(store.address)}</div>`:''}${store.phone?`<div>Hotline: ${esc(store.phone)}</div>`:''}<h1>${title}</h1><div class="ret-print-code">${esc(r.code)} • ${fmtDateTime(r.date)}</div></header><div class="ret-print-info"><div><span>Hóa đơn gốc</span><b>${esc(r.invoiceCode||inv?.code||'—')}</b></div><div><span>Khách hàng</span><b>${esc(c?.name||'Khách lẻ')}</b></div>${c?.phone?`<div><span>SĐT</span><b>${esc(c.phone)}</b></div>`:''}</div><table><thead><tr><th>Sản phẩm</th><th class="center">SL</th><th class="right">Đơn giá</th><th class="right">Thành tiền</th></tr></thead><tbody>${items}</tbody></table><div class="ret-print-total"><div><span>Giá trị phiếu</span><b>${money(r.amount)}</b></div>${r.debtOffset?`<div><span>Trừ công nợ</span><b>${money(r.debtOffset)}</b></div>`:''}<div><span>Hoàn thực tế</span><b>${money(r.refundPaid||0)}</b></div><div><span>Phương thức</span><b>${esc(r.refundMethod||'—')}</b></div></div>${r.reason?`<div class="ret-print-note"><b>Lý do:</b> ${esc(r.reason)}</div>`:''}${r.note?`<div class="ret-print-note"><b>Ghi chú:</b> ${esc(r.note)}</div>`:''}<footer><div><b>Khách hàng</b><span>Ký, ghi rõ họ tên</span></div><div><b>Nhân viên</b><span>Ký, ghi rõ họ tên</span></div></footer></div>`}
  window.openReturnPrint=(id,paper='K80')=>{const r=(db.returns||[]).find(x=>x.id===id);if(!r)return toast('Không tìm thấy phiếu trả/đổi');state.modal={type:'returnPrintPreview',r,paper};render()};
  window.printReturnNow=()=>{const m=state.modal;if(m?.type!=='returnPrintPreview')return;const html=returnDocHtml(m.r,m.paper),w=window.open('','_blank','width=900,height=900');if(!w)return toast('Trình duyệt đang chặn cửa sổ in');const width=m.paper==='K80'?'80mm':'210mm';w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(m.r.code)}</title><style>body{margin:0;font-family:Arial,sans-serif;color:#111}.return-print{box-sizing:border-box;margin:0 auto;padding:10mm;font-size:12px}.return-print.k80{width:80mm;padding:5mm;font-size:10px}.return-print.a4{width:210mm;min-height:297mm}.return-print header{text-align:center}.return-print h2{font-size:15px;margin:0 0 4px}.return-print h1{font-size:18px;margin:14px 0 4px}.return-print.k80 h1{font-size:14px}.ret-print-code{font-size:10px}.ret-print-info{margin:12px 0;border-top:1px solid #222;border-bottom:1px solid #222;padding:7px 0}.ret-print-info div,.ret-print-total div{display:flex;justify-content:space-between;gap:12px;margin:4px 0}.return-print table{width:100%;border-collapse:collapse}.return-print th,.return-print td{padding:6px 4px;border-bottom:1px solid #ddd;text-align:left}.return-print.k80 th,.return-print.k80 td{padding:4px 2px}.center{text-align:center!important}.right{text-align:right!important}.ret-print-imei{font-family:monospace;font-size:9px;margin-top:3px}.ret-print-total{margin-top:10px;border-top:1px solid #222;padding-top:7px}.ret-print-note{margin-top:8px}.return-print footer{display:grid;grid-template-columns:1fr 1fr;text-align:center;gap:30px;margin-top:36px}.return-print footer span{display:block;font-size:9px;margin-top:4px}@page{size:${m.paper==='K80'?'80mm auto':'A4'};margin:0}@media print{body{width:${width}}}</style></head><body>${html}<script>window.onload=()=>{window.print();setTimeout(()=>window.close(),300)}<\/script></body></html>`);w.document.close()};
  function returnPrintModal(m){return sheet(`Xem phiếu ${m.paper}`,`<div class="foundation-print-preview ${m.paper==='A4'?'a4':'k80'}">${returnDocHtml(m.r,m.paper)}</div><div class="split-buttons" style="margin-top:12px"><button class="btn ghost" onclick="closeModal()">Đóng</button><button class="btn primary" onclick="printReturnNow()">IN ${m.paper}</button></div>`)}

  window.productCards=productCards=function(list){if(!isDesktop())return baseProductCards(list);return list.map(p=>`<button class="item foundation-row foundation-product-row" onclick="openProductDetail(${p.id})"><div class="foundation-main-cell">${p.images?.[0]?`<img class="thumb" src="${p.images[0]}">`:'<div class="thumb">📦</div>'}<span><b>${esc(p.name)}</b><small>${esc(p.sku||'')} • ${esc(p.barcode||'Chưa có mã')}</small></span></div><div><b>${money(p.price)}</b><small>Giá vốn ${money(p.cost||0)} • Tồn ${p.stock}</small></div><div class="right"><span class="badge ${p.stock<=p.minStock?'orange':'green'}">Tồn ${p.stock}</span>${p.imeiEnabled?`<small>${availableImeis(p.id).length} IMEI/Serial</small>`:''}</div></button>`).join('')||'<div class="empty">Không tìm thấy sản phẩm.</div>'};
  window.customerCards=customerCards=function(list){if(!isDesktop())return baseCustomerCards(list);return list.map(c=>`<button class="item foundation-row foundation-customer-row" onclick="openCustomerDetail(${c.id})"><div class="foundation-main-cell"><div class="thumb">👤</div><span><b>${esc(c.name)}</b><small>${esc(c.phone||'')}${c.email?` • ${esc(c.email)}`:''}</small></span></div><div><b>${money(c.total||0)}</b><small>${esc(c.status||'')} • ${Number(c.points)||0} điểm</small></div><div class="right">${c.debt?`<span class="badge red">Nợ ${money(c.debt)}</span>`:'<span class="badge green">Đã thanh toán</span>'}<small>${(db.returns||[]).filter(r=>r.customerId===c.id&&r.status!=='Đã hủy').length} phiếu trả/đổi</small></div></button>`).join('')||'<div class="empty">Chưa có khách hàng</div>'};
  window.invoiceCards=invoiceCards=function(list){if(!isDesktop())return baseInvoiceCards(list);return list.map(inv=>{const c=customer(inv.customerId),returned=Number(inv.returnedAmount)||0;return `<button class="item foundation-row foundation-invoice-row" onclick="openInvoiceDetail(${inv.id})"><div><b>${esc(inv.code)}</b><small>${esc(c?.name||'Khách lẻ')}${inv.voucherCode?` • VC ${esc(inv.voucherCode)}`:''}</small></div><div><b>${fmtDateTime(inv.date)}</b><small>${money(inv.total)}${returned?` • trả ${money(returned)}`:''}</small></div><div class="right"><span class="badge ${inv.status==='Đã hủy'?'red':inv.debt?'red':returned?'orange':'green'}">${esc(inv.status||'Hoàn thành')}</span><small>${inv.debt?`Nợ ${money(inv.debt)}`:`Ròng ${money(netInvoiceValue(inv))}`}</small></div></button>`}).join('')||'<div class="empty">Chưa có hóa đơn.</div>'};

  window.modalView=modalView=function(){if(state.modal?.type==='customerDetail')return customerDetailModal(state.modal);if(state.modal?.type==='invoiceDetail')return invoiceDetailModal(state.modal.inv);if(state.modal?.type==='returnPrintPreview')return returnPrintModal(state.modal);return baseModalView()};
  window.render=render=function(){ensure();baseRender()};
})();
